// A browser client for Sample.WebServer in TypeScript: the console sample's queries as a page, the
// photos shown from the attachment handles a query brought back, and a live table of orders a
// command reprices. The model is generated by the Vite plugin; /api is forwarded to the server.

import { createCommands, createScry, httpTransport } from "scry-client";
import { schema, type Commands, type Sources } from "./scry.generated.ts";
import "./style.css";

// A path, not a URL: the page asks its own origin, and the dev server forwards /api to the server.
// begin-snippet: typescriptWebSetup
const scry = createScry<Sources>(schema, { transport: httpTransport({ endpoint: "/api/query" }) });
const commands = createCommands<Commands>(scry);
// end-snippet

type OrderRow = { id: number; region: string; amount: string; repriceable: boolean };
let orders: OrderRow[] = [];

async function showEmployees(): Promise<void> {
  const rows = await scry.employee
    .where(_ => _.active)
    .orderBy(_ => _.name)
    .select(_ => ({ name: _.name, status: _.status, manager: _.manager.name, department: _.department.name }))
    .toList();

  fill("employees", rows.map(_ => [_.name, _.status, _.manager ?? "", _.department ?? ""]));
}

// Each handle fetches its bytes as a request of its own, and a blob of them is what an image shows.
// begin-snippet: typescriptWebPhotos
async function showPhotos(): Promise<void> {
  const employees = await scry.employee
    .orderBy(_ => _.id)
    .select(_ => ({ id: _.id, name: _.name, photo: _.photo }))
    .toList();

  const photos = document.getElementById("photos")!;
  for (const employee of employees) {
    const figure = document.createElement("figure");
    const content = await employee.photo.open();
    if (content === null) {
      const none = document.createElement("div");
      none.className = "none";
      none.textContent = "no photo";
      figure.append(none);
    } else {
      const image = document.createElement("img");
      image.src = URL.createObjectURL(await content.blob());
      image.alt = employee.name;
      figure.append(image);
    }

    const caption = document.createElement("figcaption");
    caption.textContent = employee.name;
    figure.append(caption);
    photos.append(figure);
  }
}
// end-snippet

async function showRegions(): Promise<void> {
  const rows = await scry.order
    .groupBy(_ => _.region)
    .select(group => ({ region: group.key, total: group.sum(_ => _.amount), count: group.count() }))
    .toList();

  fill("regions", rows.map(_ => [_.region, _.total, String(_.count)]));
}

// The whole current answer, each time it changes: a reprice from this page, another tab, or the
// console sample all arrive the same way. Whether a row may be repriced is decided by the server,
// row by row, from the command's policy.
// begin-snippet: typescriptWebLive
function watchOrders(): void {
  scry.order
    .orderBy(_ => _.id)
    .select(_ => ({ id: _.id, region: _.region, amount: _.amount, repriceable: _.canRepriceOrder }))
    .live()
    .subscribe(
      answer => {
        orders = answer;
        renderOrders();
      },
      error => status(`The live query ended: ${(error as Error).message}`));
}
// end-snippet

function renderOrders(): void {
  const body = document.querySelector("#orders tbody")!;
  body.replaceChildren(...orders.map(order => {
    const row = document.createElement("tr");
    row.dataset["id"] = String(order.id);
    for (const text of [String(order.id), order.region, order.amount]) {
      row.append(cell(text));
    }

    const button = document.createElement("button");
    button.textContent = "Reprice";
    button.disabled = !order.repriceable || !commands.can("repriceOrder");
    button.addEventListener("click", () => void reprice(order.id));
    const actions = document.createElement("td");
    actions.append(button);
    row.append(actions);
    return row;
  }));
}

// A command, and its outcome. One the server decides within its sync window is final at once; a
// pending one's completion is the outcome when it lands. A refusal throws, and nothing ran.
// begin-snippet: typescriptWebCommand
async function reprice(id: number): Promise<void> {
  status(`Repricing order ${id}…`);
  try {
    const sent = await commands.send.repriceOrder({ id });
    const outcome = await sent.completion;
    if (outcome.status === "Completed") {
      status(`Order ${id} repriced.`);
      return;
    }

    status(`Order ${id} was not repriced: ${outcome.error}`);
  } catch (error) {
    status(`Order ${id} was refused: ${(error as Error).message}`);
  }
}
// end-snippet

function fill(table: string, rows: readonly (readonly string[])[]): void {
  document.querySelector(`#${table} tbody`)!.replaceChildren(...rows.map(cells => {
    const row = document.createElement("tr");
    row.append(...cells.map(cell));
    return row;
  }));
}

function cell(text: string): HTMLTableCellElement {
  const element = document.createElement("td");
  element.textContent = text;
  return element;
}

function status(text: string): void {
  document.getElementById("status")!.textContent = text;
}

// Whether the Reprice buttons are enabled is the server's word, read once and again after a denial.
commands.onCapabilitiesChanged(renderOrders);
void commands.ready;

for (const show of [showEmployees, showPhotos, showRegions]) {
  show().catch((error: unknown) => status((error as Error).message));
}

watchOrders();
